#!/usr/bin/env python3
"""Count non-empty values in each column of a CSV file."""

import argparse
import csv
import sys


def count_nonempty(path, encoding="utf-8"):
    with open(path, newline="", encoding=encoding) as fh:
        reader = csv.reader(fh)
        try:
            header = next(reader)
        except StopIteration:
            return [], 0

        counts = [0] * len(header)
        rows = 0
        for row in reader:
            if not row:
                continue
            rows += 1
            for i, value in enumerate(row[:len(counts)]):
                if value.strip():
                    counts[i] += 1
    return list(zip(header, counts)), rows


def main():
    parser = argparse.ArgumentParser(description="Count non-empty values per CSV column.")
    parser.add_argument("csv_file", help="path to the CSV file")
    parser.add_argument("--encoding", default="utf-8", help="file encoding (default: utf-8)")
    args = parser.parse_args()

    try:
        results, rows = count_nonempty(args.csv_file, args.encoding)
    except OSError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    if not results:
        print("file is empty", file=sys.stderr)
        return 1

    width = max(len(name) for name, _ in results)
    print(f"rows: {rows}")
    for name, count in results:
        print(f"{name:<{width}}  {count}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
